export type Chapter = {
  slug: ChapterSlug;
  n: number;
  title: string;
  summary: string;
  level: "Beginner" | "Intermediate" | "Advanced" | "Pro Max" | "Enterprise";
};

export type GuideStep = {
  id: number;
  chapter: ChapterSlug;
  lesson: number;
  title: string;
  command: string;
  explain: string;
  tip?: string;
  danger?: string;
  output?: string;
};

